import{c as t,Q as a,j as n,m as o}from"./chunks/framework.DK3sgdKX.js";const u=JSON.parse('{"title":"Pattern resource contract (M1)","description":"","frontmatter":{},"headers":[],"relativePath":"PATTERN_RESOURCE_CONTRACT.md","filePath":"PATTERN_RESOURCE_CONTRACT.md","lastUpdated":1786241303000}'),s={name:"PATTERN_RESOURCE_CONTRACT.md"};function i(r,e,c,d,l,p){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="pattern-resource-contract-m1" tabindex="-1">Pattern resource contract (M1) <a class="header-anchor" href="#pattern-resource-contract-m1" aria-label="Permalink to &quot;Pattern resource contract (M1)&quot;">​</a></h1><p><code>pystg.pattern</code> is a versioned authoring document that compiles directly into the formal game runtime. The JSON document is the source of truth; generated Python is an optional compatibility/export artifact.</p><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*.pystg.json</span></span>
<span class="line"><span>  -&gt; PatternDocument (validated recipe)</span></span>
<span class="line"><span>  -&gt; PatternCompiler (resource resolution and static precomputation)</span></span>
<span class="line"><span>  -&gt; PatternProgram (immutable IR)</span></span>
<span class="line"><span>  -&gt; PatternRunner (fixed 60 Hz scheduling)</span></span>
<span class="line"><span>  -&gt; StageContext.create_bullets_batch</span></span>
<span class="line"><span>  -&gt; OptimizedBulletPool (NumPy/Numba-compatible bullet state)</span></span></code></pre></div><p>The editor preview and gameplay must consume the same <code>PatternProgram</code>, <code>PatternRunner</code>, <code>StageContext</code>, and bullet-pool behavior. An editor may draw a grid, handles, selections, guides, and diagnostic overlays above that output, but an approximate editor-only simulator is not formal preview evidence.</p><h2 id="v1-document-sections" tabindex="-1">V1 document sections <a class="header-anchor" href="#v1-document-sections" aria-label="Permalink to &quot;V1 document sections&quot;">​</a></h2><p>The published schema is <a href="schemas/pystg-pattern-v1.schema.json"><code>schemas/pystg-pattern-v1.schema.json</code></a>. It uses the common resource header plus these sections:</p><ul><li><code>bullet</code>: a type/color alias or direct <code>res://atlas.json#sprite</code> reference.</li><li><code>shape</code>: <code>ring</code>, <code>arc</code>, <code>line</code>, <code>spiral</code>, <code>random</code>, or legacy-compatible <code>flower</code>, including count and logical runtime origin.</li><li><code>aim</code>: a fixed direction or a direction sampled toward the player at spawn.</li><li><code>schedule</code>: integer-frame delay and interval, bursts per loop, and finite or infinite loop count (<code>null</code>).</li><li><code>motion</code>: initial speed plus data-oriented pool fields for friction, spin, time scale, lifetime, scale, and axis bounce.</li><li><code>modifiers</code>: deterministic per-burst angle/speed offsets and random-speed variation.</li><li><code>seed</code>: a stable non-negative 63-bit seed.</li></ul><p>Unknown fields are rejected in v1. A shape can contain at most 4096 bullets and a schedule at most 4096 distinct burst templates. Compilation additionally rejects programs that would precompute more than 1,000,000 bullet records.</p><h2 id="compilation-and-diagnostics" tabindex="-1">Compilation and diagnostics <a class="header-anchor" href="#compilation-and-diagnostics" aria-label="Permalink to &quot;Compilation and diagnostics&quot;">​</a></h2><p><code>PatternCompiler</code> resolves aliases or direct sprite fragments, hashes document and dependency contents, optionally resolves the sprite&#39;s integer runtime index, and precomputes one immutable <code>BurstTemplate</code> per burst in a schedule loop. Its cache identity includes the schema version, canonical document JSON, resource contents, and sprite index.</p><p>Compilation failures carry structured diagnostics with severity, code, resource UUID, property path, and message. Missing files, missing fragments, invalid alias maps, oversized programs, and sprite-index failures are errors; the compiler does not silently substitute an authored resource.</p><h2 id="runner-and-ownership" tabindex="-1">Runner and ownership <a class="header-anchor" href="#runner-and-ownership" aria-label="Permalink to &quot;Runner and ownership&quot;">​</a></h2><p><code>PatternRunner.tick()</code> advances in integer frames. Its lifecycle is start, pause/resume, reset, and stop. Resetting replays the same immutable program and seed deterministically. Every runner has a non-zero owner tag, used to clear, translate, or change time scale only for that instance&#39;s live bullets.</p><p>Dense bullets are never scene nodes. A burst is written to the structured NumPy pool as one batch, and common motion remains in pool fields and optimized kernels. Pattern execution installs no per-bullet Python update/death/emitter callbacks.</p><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><p><code>PatternDocument.from_pattern_spec()</code> imports the existing Pattern Lab model, including its ring, arc, spiral, flower, interval, multi-burst, angle-offset, and infinite-loop behavior. This path does not generate or reverse-parse Python.</p><p>Use <code>tools/benchmark_pattern_runtime.py</code> for the representative M1 dense-burst measurement. Performance evidence is environment-specific and is recorded in the editor roadmap completion log.</p>`,18)])])}const h=t(s,[["render",i]]);export{u as __pageData,h as default};
